def do_algebra(operator, operand):
    if len(operator) != len(operand) - 1:
        return "Invalid input: Length of operator list should be one less than the length of operand list"

    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
