    if planet1 not in planets or planet2 not in planets:
        return ()

    start_index = planets.index(planet1)
    end_index = planets.index(planet2)

    if start_index < end_index:
        sorted_planets = planets[start_index+1:end_index]
    else:
        sorted_planets = planets[end_index+1:start_index]

    return tuple(sorted(sorted_planets, key=lambda x: planets.index(x)))

