    # Check if the given sides can form a triangle
    if a + b > c and a + c > b and b + c > a:
        # Calculate the square of each side
        a_square = a ** 2
        b_square = b ** 2
        c_square = c ** 2

        # Identify the longest side
        longest_side = max(a_square, b_square, c_square)

        # Check if the sum of the squares of the two shorter sides is equal to the square of the longest side
        if longest_side == a_square + b_square + c_square - longest_side:
